CREATE OR REPLACE FUNCTION public.class_riposte(p_world uuid, p_uid uuid, p_id integer, p_share double precision, p_n integer)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare c creature; pl player; b jsonb; v_go int;
begin
  for v_go in 1 .. greatest(1, coalesce(p_n, 1)) loop
    select * into c from creature where world_id = p_world and id = p_id;
    select * into pl from player where world_id = p_world and uid = p_uid;
    exit when c.id is null or c.health <= 0 or pl.uid is null
      or sqrt((creature_x(c) - pl.x) ^ 2 + (creature_y(c) - pl.y) ^ 2) > melee_reach(p_world, p_uid);
    b := class_blow(p_world, p_uid, p_id, p_share);
    perform tell(p_world, p_uid,
      case when not (b->>'landed')::boolean then 'Riposte missed: ' || (b->>'name') || '.'
              when (b->>'died')::boolean then 'Riposte: ' || (b->>'name') || ' killed.'
              else 'Riposte' || case when (b->>'crit')::boolean then ', critical' else '' end
                || ': ' || (b->>'name') || ' ' || (b->>'left') || '/' || (b->>'of') || '.' end, 'fight');
  end loop;
end $function$
